"""Unreal Engine 5 export: FBX + textures + generated import script."""

import json
import os

from . import common, ue_remote

# The script runs inside Unreal's Python. It only uses long-standing editor APIs
# (AssetImportTask, MaterialEditingLibrary) available in UE 5.0 - 5.x.
_UE_SCRIPT = r'''
# Generated by Zapekanka (Blender). Run in Unreal: Tools > Execute Python Script.
import json
import unreal

MANIFEST = json.loads(r"""__MANIFEST__""")

tools = unreal.AssetToolsHelpers.get_asset_tools()
mel = unreal.MaterialEditingLibrary
eal = unreal.EditorAssetLibrary
PROPS = {
    "base_color": unreal.MaterialProperty.MP_BASE_COLOR,
    "normal": unreal.MaterialProperty.MP_NORMAL,
    "roughness": unreal.MaterialProperty.MP_ROUGHNESS,
    "metallic": unreal.MaterialProperty.MP_METALLIC,
    "ao": unreal.MaterialProperty.MP_AMBIENT_OCCLUSION,
    "emission": unreal.MaterialProperty.MP_EMISSIVE_COLOR,
    "opacity": unreal.MaterialProperty.MP_OPACITY_MASK,
}


def task(filename, dest, options=None):
    t = unreal.AssetImportTask()
    t.set_editor_property("filename", filename)
    t.set_editor_property("destination_path", dest)
    t.set_editor_property("automated", True)
    t.set_editor_property("replace_existing", True)
    t.set_editor_property("save", False)
    if options is not None:
        t.set_editor_property("options", options)
    return t


def imported(t):
    paths = list(t.get_editor_property("imported_object_paths") or [])
    for p in paths:
        asset = unreal.load_asset(p)
        if asset is not None:
            return asset
    return None


def configure_texture(tex, info):
    kind = info["kind"]
    if kind == "normal":
        tex.set_editor_property("compression_settings", unreal.TextureCompressionSettings.TC_NORMALMAP)
        tex.set_editor_property("srgb", False)
        tex.set_editor_property("lod_group", unreal.TextureGroup.TEXTUREGROUP_WORLD_NORMAL_MAP)
        tex.set_editor_property("flip_green_channel", MANIFEST["normal_format"] == "OPENGL")
    elif info["srgb"]:
        tex.set_editor_property("compression_settings", unreal.TextureCompressionSettings.TC_DEFAULT)
        tex.set_editor_property("srgb", True)
    else:
        tex.set_editor_property("compression_settings", unreal.TextureCompressionSettings.TC_MASKS)
        tex.set_editor_property("srgb", False)


def sampler_type(info):
    if info["kind"] == "normal":
        return unreal.MaterialSamplerType.SAMPLERTYPE_NORMAL
    if info["srgb"]:
        return unreal.MaterialSamplerType.SAMPLERTYPE_COLOR
    return unreal.MaterialSamplerType.SAMPLERTYPE_MASKS


def build_material(ts, textures):
    path = ts["dest"] + "/" + ts["material"]
    if eal.does_asset_exist(path):
        mat = unreal.load_asset(path)
        mel.delete_all_material_expressions(mat)
    else:
        mat = tools.create_asset(ts["material"], ts["dest"], unreal.Material, unreal.MaterialFactoryNew())
    y = -300
    masked = False
    for info in ts["textures"]:
        tex = textures.get(info["file"])
        if tex is None or not info["connect"]:
            continue
        expr = mel.create_material_expression(mat, unreal.MaterialExpressionTextureSample, -700, y)
        expr.set_editor_property("texture", tex)
        expr.set_editor_property("sampler_type", sampler_type(info))
        y += 280
        for pin, target, invert in info["connect"]:
            prop = PROPS.get(target)
            if prop is None:
                continue
            source, out = expr, pin
            if invert:
                inv = mel.create_material_expression(mat, unreal.MaterialExpressionOneMinus, -350, y - 260)
                mel.connect_material_expressions(expr, pin, inv, "")
                source, out = inv, ""
            mel.connect_material_property(source, out, prop)
            if target == "opacity":
                masked = True
    if masked:
        mat.set_editor_property("blend_mode", unreal.BlendMode.BLEND_MASKED)
    mel.recompile_material(mat)
    return mat


def mesh_options():
    opts = unreal.FbxImportUI()
    opts.set_editor_property("import_mesh", True)
    opts.set_editor_property("import_textures", False)
    opts.set_editor_property("import_materials", False)
    opts.set_editor_property("import_as_skeletal", False)
    opts.set_editor_property("mesh_type_to_import", unreal.FBXImportType.FBXIT_STATIC_MESH)
    data = opts.get_editor_property("static_mesh_import_data")
    data.set_editor_property("combine_meshes", True)
    data.set_editor_property("auto_generate_collision", True)
    data.set_editor_property("normal_import_method", unreal.FBXNormalImportMethod.FBXNIM_IMPORT_NORMALS_AND_TANGENTS)
    return opts


for ts in MANIFEST["sets"]:
    tex_tasks = [task(info["path"], ts["dest"] + "/Textures") for info in ts["textures"]]
    if tex_tasks:
        tools.import_asset_tasks(tex_tasks)
    textures = {}
    for t, info in zip(tex_tasks, ts["textures"]):
        tex = imported(t)
        if tex is None:
            unreal.log_warning("Zapekanka: could not import %s" % info["path"])
            continue
        configure_texture(tex, info)
        textures[info["file"]] = tex
    mat = build_material(ts, textures) if textures else None
    if ts.get("mesh"):
        mt = task(ts["mesh"], ts["dest"], mesh_options())
        tools.import_asset_tasks([mt])
        mesh = imported(mt)
        if mesh is not None and mat is not None and isinstance(mesh, unreal.StaticMesh):
            for i in range(len(mesh.get_editor_property("static_materials"))):
                mesh.set_material(i, mat)
    eal.save_directory(ts["dest"], only_if_is_dirty=False, recursive=True)
    print("ZAPEKANKA: imported %s (%d textures)" % (ts["name"], len(textures)))
'''

# Material wiring for UE: (pin, property, invert) per texture kind.
_PINS = "RGBA"


def _connections(f):
    from ..core.maps import expand_channels

    chans = expand_channels(f["channels"])
    keys = [c.map for c in chans]
    if f["id"] == "normal":
        return "normal", [("RGB", "normal", False)]
    if keys[:3] in (["base_color"] * 3, ["emission"] * 3):
        conns = [("RGB", keys[0], False)]
        if len(chans) == 4 and chans[3].map == "opacity":
            conns.append(("A", "opacity", chans[3].invert))
        return keys[0], conns
    if len(chans) == 1:
        if chans[0].map in ("roughness", "metallic", "ao", "opacity"):
            return chans[0].map, [("R", chans[0].map, chans[0].invert)]
        return chans[0].map, []
    conns = []
    seen = set()
    for i, ch in enumerate(chans):
        if ch.is_constant or ch.map in seen or ch.map not in ("roughness", "metallic", "ao", "opacity"):
            continue
        seen.add(ch.map)
        conns.append((_PINS[i], ch.map, ch.invert))
    return "mask", conns


def build_manifest(context, sets, root):
    s = context.scene.zapekanka
    e = s.export
    manifest = {"normal_format": s.normal_format, "sets": []}
    for ts in sets:
        dest = e.ue_content_path.rstrip("/") + "/" + ts.name
        entry = {
            "name": ts.name,
            "dest": dest,
            "material": s.material_template.replace("{name}", ts.name),
            "mesh": ts.export_mesh,
            "textures": [],
        }
        for f in ts.export_files:
            kind, conns = _connections(f)
            entry["textures"].append({
                "file": os.path.basename(f["path"]),
                "path": f["path"].replace("\\", "/"),
                "kind": kind,
                "srgb": bool(f.get("srgb")),
                "connect": conns,
            })
        manifest["sets"].append(entry)
    return manifest


def script_for(manifest):
    return _UE_SCRIPT.replace("__MANIFEST__", json.dumps(manifest, indent=1))


def export(context, sets, root, report):
    s = context.scene.zapekanka
    e = s.export
    for ts in sets:
        folder = os.path.join(root, ts.name)
        os.makedirs(folder, exist_ok=True)
        mat = common.baked_material(context, ts)
        mesh_name = s.mesh_template.replace("{name}", ts.name)
        ts.export_mesh = None
        if ts.lows:
            groups = [{"name": mesh_name, "objects": ts.lows, "material": mat, "pivot": ts.lows[0]}]
            with common.export_objects(context, groups, e.triangulate) as objs:
                path = os.path.join(folder, mesh_name + ".fbx")
                common.export_fbx(context, objs, path, "DEFAULT", e.scale, e.triangulate)
                ts.export_mesh = path.replace("\\", "/")
        ts.export_files = common.copy_textures(ts, os.path.join(folder, "Textures")) if e.include_textures else []
    manifest = build_manifest(context, sets, root)
    code = script_for(manifest)
    script_path = os.path.join(root, "import_to_unreal.py")
    with open(script_path, "w", encoding="utf-8") as fh:
        fh.write(code)
    if e.ue_live:
        from ..prefs import get_prefs

        prefs = get_prefs()
        ok, message = ue_remote.send(
            code,
            group=prefs.ue_multicast_group if prefs else "239.0.0.1",
            port=prefs.ue_multicast_port if prefs else 6766,
            bind=prefs.ue_multicast_bind if prefs else "127.0.0.1",
            timeout=float(prefs.ue_timeout if prefs else 5),
        )
        if ok:
            report({"INFO"}, "Sent to Unreal: %s" % (message.splitlines()[-1] if message else "done"))
            return script_path
        report({"WARNING"}, "%s. Run %s in Unreal (Tools > Execute Python Script)" % (message, script_path))
        return script_path
    report({"INFO"}, "Exported. Run %s in Unreal (Tools > Execute Python Script)" % script_path)
    return script_path
